steps.command:
set -e; python3 - <<'PY'
import fcntl
lock=open('/app/data/ledger.lock','a')
try: fcntl.flock(lock,fcntl.LOCK_EX|fcntl.LOCK_NB)
except BlockingIOError: print('ledger_lock_probe=blocked')
else: raise SystemExit('exclusive ledger lock was unexpectedly available')
PY
pid=$(cat /app/gateway.pid); test -r /proc/$pid/cmdline; printf 'gateway_pid=%s command=' "$pid"; tr '\0' ' ' < /proc/$pid/cmdline; echo
